<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); try { $m = app(\Kreait\Firebase\Contract\Messaging::class); $notification = \Kreait\Firebase\Messaging\Notification::create("Test Title", "Test Body"); $message = \Kreait\Firebase\Messaging\CloudMessage::new()->withTopic("all_users")->withNotification($notification); $m->send($message); echo "Push sent successfully.\n"; } catch (\Exception $e) { echo "ERROR: " . $e->getMessage() . "\n"; }
